import{_ as t,o,c as a,a0 as n}from"./chunks/framework.ysVzM4be.js";const f=JSON.parse('{"title":"ADR 0005: A work cycle ends at close","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0005-a-work-cycle-ends-at-close.md","filePath":"adr/0005-a-work-cycle-ends-at-close.md"}'),c={name:"adr/0005-a-work-cycle-ends-at-close.md"};function d(s,e,i,r,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0005-a-work-cycle-ends-at-close" tabindex="-1">ADR 0005: A work cycle ends at close <a class="header-anchor" href="#adr-0005-a-work-cycle-ends-at-close" aria-label="Permalink to &quot;ADR 0005: A work cycle ends at close&quot;">​</a></h1><p>Status: accepted Date: 2026-08-31</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The work cycle model held a finished ticket in <code>done</code> until it left all sources and later returned. Auto-handoff and workflow routing change the needs: the operator accepts a settled agent turn, and the ticket must be usable again at once while its source item is still present and active. Holding the ticket as <code>done</code> would hide it from handoff, and re-arming it would need a special case for every just-closed ticket.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Closing a cycle, by the operator or by auto-close, ends the work cycle, stores the completion trace, and returns the ticket to <code>open</code> at once with an incremented cycle number. A cycle can hold several handoffs, so a workflow chain (implement, then review, then merge) is one cycle. <code>done</code> stops being a resting ticket state; it lives only in the work cycle record. The resting states are <code>open</code>, <code>handed-off</code>, <code>running</code>, and <code>awaiting</code>.</p><p>The considered alternatives:</p><ul><li>Hold the ticket as <code>done</code> until it leaves all sources and returns, the old model. Rejected: a closed ticket would stay invisible to handoff while its source item is still active, and auto-handoff would need a re-arm rule for every just-closed ticket.</li><li>Keep <code>done</code> as a resting state and add a separate re-open action. Rejected: two ways to end one cycle, and a state that means both &quot;finished&quot; and &quot;waiting to be re-opened&quot;.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The forward note in ADR 0002 (&quot;agent state for the <code>running</code> and <code>done</code> ticket states&quot;) lands as <code>running</code> and <code>awaiting</code> instead.</li><li>Immediate re-availability makes the close-and-rehandoff loop possible, so the per-ticket handoff limit bounds auto-handoff.</li><li>Source facts still never reset factory state. Close is a factory action and never touches the external source item.</li></ul>',10)])])}const p=t(c,[["render",d]]);export{f as __pageData,p as default};
